 function RecordForm({kind,record,extras,pipe,u,team,list,can,run,save,M,busy}:A){const [v,V]=useState<A>(()=>({...({contacts:{name:'',email:'',phone:'',company:'',tags:[],custom:{},optOut:false},companies:{name:'',industry:'',website:''},opportunities:{name:'',contact:'',pipeline:pipe?.id,stage:pipe?.stages[0]?.id,owner:u.id,...(can('values')?{value:0,currency:'USD'}:{}),custom:{}},leads:{name:'',contact:''},fields:{name:'',type:'Text',entity:'opportunities',pipeline:pipe?.id,options:[]},roles:{name:'',base:'User',permissions:['view']},pipelines:{name:'',stages:[{id:crypto.randomUUID(),name:'New',type:'open',required:[]},{id:crypto.randomUUID(),name:'Won',type:'won',required:[]},{id:crypto.randomUUID(),name:'Lost',type:'lost',required:[]}]},notes:{body:'',contact:extras.contact}} as A)[kind],...record,...extras}));const change=(k:string,val:A)=>V({...v,[k]:val});const input=(k:string,label:string,type='text',req=false)=><Field label={label}><input type={type} value={v[k]??''} required={req} onChange={e=>change(k,type==='number'?Number(e.target.value):e.target.value)}/></Field>;const select=(k:string,label:string,opts:A,optional=false)=><Field label={label}><select value={v[k]||''} onChange={e=>change(k,e.target.value)} required={!optional}><option value="">Select…</option>{opts.map((o:A)=><option key={o.id||o} value={o.id||o}>{o.name||o}</option>)}</select></Field>;
 return <form className="modal-form" onSubmit={e=>{e.preventDefault();run(()=>save(kind,v,record));}}>{!['notes','leads'].includes(kind)&&input('name',kind==='contacts'?'Full name':singular[kind]+' name','text',true)}{kind==='contacts'&&<><div className="form-grid">{input('email','Email','email')}{input('phone','Phone number','tel')}</div>{select('company','Company (optional)',list('companies'),true)}<Field label="Tags, separated by commas"><input value={v.tags.join(', ')} onChange={e=>change('tags',e.target.value.split(',').map(t=>t.trim()).filter(Boolean))}/></Field><label className="checkbox-label"><input type="checkbox" checked={v.optOut||false} onChange={e=>change('optOut',e.target.checked)}/>Contact has opted out of messaging</label></>}{kind==='companies'&&<>{input('industry','Industry')}{input('website','Website','url')}</>}{kind==='leads'&&<>{select('contact','Contact',list('contacts'))}{input('name','Lead name','text',true)}{!list('contacts').length&&<div className="info-banner">Create a contact before adding a lead.</div>}</>}{kind==='opportunities'&&<>{select('contact','Contact',list('contacts'))}<div className="form-grid"><Field label="Pipeline"><select value={v.pipeline} onChange={e=>{const p=list('pipelines').find((p:A)=>p.id===e.target.value);V({...v,pipeline:p.id,stage:p.stages[0].id,custom:{}});}}>{list('pipelines').map((p:A)=><option key={p.id} value={p.id}>{p.name}</option>)}</select></Field>{select('stage','Stage',list('pipelines').find((p:A)=>p.id===v.pipeline)?.stages||[])}</div>{select('owner','Assigned employee',can('assignment')?team:team.filter((x:A)=>x.id===u.id))}{can('values')&&<div className="form-grid">{input('value','Value in minor units (cents)','number',true)}{select('currency','Currency',['USD','GBP','EUR','PKR','AUD','CAD','AED'])}</div>}</>}{kind==='fields'&&<><div className="form-grid">{select('type','Type',['Text','Number','Date','Dropdown','Checkbox'])}{select('entity','Applies to',['contacts','opportunities'])}</div>{v.entity==='opportunities'&&select('pipeline','Pipeline',list('pipelines'))}{v.type==='Dropdown'&&<Field label="Options, separated by commas"><input value={v.options.join(', ')} onChange={e=>change('options',e.target.value.split(',').map(t=>t.trim()).filter(Boolean))} required/></Field>}<div className="info-banner">Fields appear immediately on matching forms. Archiving preserves existing values.</div></>}{kind==='roles'&&<>{select('base','Base level',['User','Admin'])}<div className="permissions-grid">{['view','create','edit','delete','export','values','assignment','integrations','audit','configuration','team'].map(p=><label key={p}><input type="checkbox" checked={v.permissions.includes(p)} onChange={e=>change('permissions',e.target.checked?[...v.permissions,p]:v.permissions.filter((x:string)=>x!==p))}/>{p==='values'?'View monetary values':p}</label>)}</div></>}{kind==='notes'&&<><Field label="Activity type"><select value={v.type||'Note'} onChange={e=>change('type',e.target.value)}><option>Note</option><option>Call log</option></select></Field><Field label="Your note"><textarea rows={5} required maxLength={5000} value={v.body} onChange={e=>change('body',e.target.value)}/></Field></>}{list('fields').filter((f:A)=>!f.archived&&f.entity===kind&&(kind!=='opportunities'||f.pipeline===v.pipeline)).map((f:A)=><Field label={f.name} key={f.id}>{f.type==='Dropdown'?<select value={v.custom?.[f.id]||''} onChange={e=>change('custom',{...v.custom,[f.id]:e.target.value})}><option value="">Select…</option>{f.options.map((x:string)=><option key={x}>{x}</option>)}</select>:<input type={({Text:'text',Number:'number',Date:'date',Checkbox:'checkbox'} as A)[f.type]} checked={f.type==='Checkbox'?!!v.custom?.[f.id]:undefined} value={f.type==='Checkbox'?undefined:v.custom?.[f.id]??''} onChange={e=>change('custom',{...v.custom,[f.id]:f.type==='Checkbox'?e.target.checked:f.type==='Number'?Number(e.target.value):e.target.value})}/>}</Field>)}<div className="modal-actions">{record&&can('delete')&&<button className="button danger" type="button" onClick={()=>M({type:'delete',kind,record})}><Trash2 size={14}/>Delete</button>}<button className="button" type="button" onClick={()=>M(null)}>Cancel</button><button className="button primary" disabled={busy}>{busy?'Saving…':record?'Save changes':'Create '+singular[kind]}<Check size={14}/></button></div></form>;}

 function PipelineEditor({record,list,run,save,busy}:A){const [v,V]=useState<A>(record);const update=(i:number,k:string,value:A)=>V({...v,stages:v.stages.map((st:A,j:number)=>i===j?{...st,[k]:value}:st)});return <form className="modal-form" onSubmit={e=>{e.preventDefault();run(()=>save('pipelines',v,record));}}><Field label="Pipeline name"><input value={v.name} required onChange={e=>V({...v,name:e.target.value})}/></Field>{v.stages.map((st:A,i:number)=><div className="stage-editor" key={st.id}><div className="stage-edit-row"><span className="stage-order">{i+1}</span><input aria-label="Stage name" value={st.name} onChange={e=>update(i,'name',e.target.value)} required/><select aria-label="Stage outcome" value={st.type} onChange={e=>update(i,'type',e.target.value)}><option value="open">Open</option><option value="won">Won</option><option value="lost">Lost</option></select><button type="button" aria-label="Move stage up" disabled={!i} onClick={()=>{const a=[...v.stages];[a[i-1],a[i]]=[a[i],a[i-1]];V({...v,stages:a});}}>↑</button><button type="button" className="icon-button" aria-label="Remove stage" onClick={()=>V({...v,stages:v.stages.filter((_:A,j:number)=>j!==i)})}><Trash2 size={14}/></button></div><div className="stage-required"><small>Required fields</small>{list('fields').filter((f:A)=>f.pipeline===v.id&&!f.archived).map((f:A)=><label key={f.id}><input type="checkbox" checked={st.required?.includes(f.id)||false} onChange={e=>update(i,'required',e.target.checked?[...st.required,f.id]:st.required.filter((x:string)=>x!==f.id))}/>{f.name}</label>)}</div></div>)}<button className="button" type="button" onClick={()=>V({...v,stages:[...v.stages,{id:crypto.randomUUID(),name:'New stage',type:'open',required:[]}]})}><Plus size={14}/>Add stage</button><div className="info-banner">Move opportunities before deleting their stage. Each pipeline requires a won and lost stage.</div><div className="modal-actions"><button className="button primary" disabled={busy}>Save pipeline <Check size={14}/></button></div></form>;}


